using Microsoft.AspNetCore.Identity;

public class CustomPasswordValidator<TUser> : IPasswordValidator<TUser>
    where TUser : IdentityUser
{
    public Task<IdentityResult> ValidateAsync(
        UserManager<TUser> manager,
        TUser user,
        string password)
    {
        var errors = new List<IdentityError>();

        if (password.Length < 12)
            errors.Add(new IdentityError
            {
                Code = "PasswordTooShort",
                Description = "Password must be at least 12 characters."
            });

        if (!password.Any(char.IsDigit))
            errors.Add(new IdentityError
            {
                Code = "PasswordRequiresDigit",
                Description = "Password must contain at least one digit."
            });

        if (!password.Any(char.IsUpper))
            errors.Add(new IdentityError
            {
                Code = "PasswordRequiresUpper",
                Description = "Password must contain an uppercase letter."
            });

        return Task.FromResult(
            errors.Count == 0
                ? IdentityResult.Success
                : IdentityResult.Failed(errors.ToArray())
        );
    }
}

// Register
builder.Services.AddScoped<IPasswordValidator<ApplicationUser>,
    CustomPasswordValidator<ApplicationUser>>();

builder.Services.Configure<IdentityOptions>(options =>
{
    options.Password.RequireDigit = true;
    options.Password.RequiredLength = 12;
    options.Password.RequireNonAlphanumeric = true;
    options.Password.RequireUppercase = true;
    options.Password.RequireLowercase = true;
    options.Password.RequiredUniqueChars = 4;
});
